    local function VM_l1lll(d, k, m)
        local R_IO0lO = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_IO0lO, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_IO0lO)
    end

    -- Execution Guard
    local F_O1ll1l = loadstring(VM_l1lll(B_01IlIIll, 71, 3))
